import json
from pathlib import Path

data_dir = Path('/app/data')
out_path = Path('/app/output/oscillation_report.json')
out_path.parent.mkdir(parents=True, exist_ok=True)

prefs = json.loads((data_dir/'preferences.json').read_text())
route_events = json.loads((data_dir/'route_events.json').read_text())
solutions = json.loads((data_dir/'possible_solutions.json').read_text())

# --- oscillation detection (preference cycle) ---
pref_next = {int(k): int(v['prefer_via']) for k, v in prefs.items()}

def find_cycle(pref_map):
    visited_global = set()
    for start in list(pref_map):
        if start in visited_global:
            continue
        path = []
        idx = {}
        cur = start
        while cur in pref_map:
            if cur in idx:
                return path[idx[cur):]  # cycle
            if cur in visited_global:
                break
            idx[cur] = len(path)
            path.append(cur)
            cur = pref_map[cur]
        visited_global.update(path)
    return None

# Fix syntax error in slicing

def find_cycle(pref_map):
    visited_global = set()
    for start in list(pref_map):
        if start in visited_global:
            continue
        path = []
        idx = {}
        cur = start
        while cur in pref_map:
            if cur in idx:
                return path[idx[cur]:]
            if cur in visited_global:
                break
            idx[cur] = len(path)
            path.append(cur)
            cur = pref_map[cur]
        visited_global.update(path)
    return None

cycle = find_cycle(pref_next)
osc_detected = cycle is not None
cycle = cycle or []

# --- route leak detection (valley-free violation) ---
# Learned from provider/peer => may export only to customers.
leaks = []
for ev in route_events:
    src_t = ev.get('source_type')
    dst_t = ev.get('destination_type')
    if src_t in ('provider', 'peer') and dst_t != 'customer':
        leaks.append({
            'leaker_as': int(ev['advertiser_asn']),
            'source_as': int(ev['source_asn']),
            'destination_as': int(ev['destination_asn']),
            'source_type': src_t,
            'destination_type': dst_t,
        })

leak_detected = len(leaks) > 0

# --- solution evaluation ---

def eval_solution(s: str):
    sl = ' '.join(s.lower().split())

    prohibited = (
        'disable hub peering' in sl
        or sl.startswith('disable ') and 'peering' in sl
    )
    if prohibited:
        return False, False

    # Oscillation: must break/override the 65002<->65003 preference cycle, or enforce deterministic forwarding.
    osc = False
    if 'update routing preference' in sl and 'stop preferring' in sl:
        osc = True
    elif 'set route preference hierarchy' in sl:
        osc = True
    elif 'routing intent' in sl:
        osc = True
    elif 'user defined route' in sl or 'udr' in sl:
        osc = True
    elif 'filter out routes learned from hub2' in sl and 'export policy' in sl:
        osc = True

    # Route leak: must prevent provider/peer-learned routes being sent to peers/providers (or block acceptance).
    leak = False
    if 'no-export' in sl and 'provider' in sl and 'peer' in sl:
        leak = True
    elif 'block announcing provider routes' in sl and 'peer' in sl:
        leak = True
    elif 'export policy' in sl and 'block announcing provider routes' in sl:
        leak = True
    elif 'export policy' in sl and 'provider routes' in sl and 'peer' in sl:
        leak = True
    elif 'ingress filtering' in sl and 'as_path' in sl and '65001' in sl:
        leak = True
    elif 'routing intent' in sl:
        leak = True

    return osc, leak

solution_results = {}
for s in solutions:
    osc_res, leak_res = eval_solution(s)
    solution_results[s] = {
        'oscillation_resolved': bool(osc_res),
        'route_leak_resolved': bool(leak_res),
    }

report = {
    'oscillation_detected': bool(osc_detected),
    'oscillation_cycle': [int(x) for x in cycle],
    'affected_ases': sorted({int(x) for x in cycle}),
    'route_leak_detected': bool(leak_detected),
    'route_leaks': leaks,
    'solution_results': solution_results,
}

out_path.write_text(json.dumps(report, indent=2, sort_keys=False) + '\n')
print(f'Wrote {out_path}')
PY"}

